class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        def substrings(x: str):
            res = [""]
            n = len(x)
            for i in range(n):
                for j in range(i + 1, n + 1):
                    res.append(x[i:j])
            return res

        subs_s = substrings(s)
        subs_t = substrings(t)

        ans = 0
        for a in subs_s:
            for b in subs_t:
                candidate = a + b
                if len(candidate) > ans and candidate == candidate[::-1]:
                    ans = len(candidate)

        return ans
